    return { field: fields.match, value: part.match };
  if ("store" in part)
    return { field: fields.store, value: part.store };
  if ("named" in part)
    return { field: fields.named, value: "" };
  if ("types" in part)
    return { field: fields.types, value: "" };
  if ("any" in part) {
    const each = await Promise.all(part.any.map((inner) => partSaid(inner, titleOf)));
    const one = each.every(({ field }) => field === each[0].field);
    return one ? { field: each[0].field, value: each.map(({ value }) => value).join(" or ") } : { field: "Either", value: each.map(inTitle).join(" or ") };
