import type { Id } from "../../src/store/id.ts";
import type { Declaration, Given, HolonOf, Space } from "../../src/interface/component.ts";
import type { BriefBody, BriefSettings } from "./bodies.ts";
import { h } from "./jsx.ts";
import { faceOf, isConfidence, markdown, placed, slotOf } from "./prose.ts";
import { Way } from "./way.tsx";

// A brief, in either kind of slot. In full: the way down to it, its title
// and prose, each part its prose places a slot where it stands, and its
// parts beneath, a slot of them all; its own values it draws, and what they
// point at it opens as slots, offering them a face, so a brief in full
// never trickles its fullness into what it holds. As a face: its number,
// title and first paragraph, and how many briefs stand beneath it. A
// brief's parts are numbered by where they stand, unless it keeps them by
// time, as a day's words are.

export const declared = {
  title: "Brief",
  says: "A brief: in full, the way down to it, its title and prose, the parts its prose places and its parts beneath, each a slot; as a face, its number, title and first paragraph.",
  takes: ["brief"],
  kinds: ["full", "face"],
  settings: {
    number: {
      says: "Its number where it stands among its whole's parts, as 2.3, drawn before its title as a face.",
      shape: "string",
      optional: true,
    },
  },
  reads: ["holders", "holon"],
} satisfies Declaration;

export const style = `
.reader h1 .number {
  color: var(--quiet);
  font-weight: 400;
  margin-right: 0.4em;
}

.reader .status {
  font: var(--smaller) / 1 var(--sans);
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--quiet);
  border: var(--hairline) solid var(--line);
  border-radius: var(--pill);
  padding: 0.3em 0.7em;
  vertical-align: middle;
  margin-left: 0.6em;
}

.reader .prose > .block:first-child > p {
  font-size: var(--lead);
}

.reader .confidence > p {
  color: var(--quiet);
  font-size: var(--aside);
}


.reader :not(pre) > code {
  font-size: var(--aside);
}

.reader blockquote {
  margin: var(--gap) 0;
  padding-left: var(--gap);
  border-left: var(--rule) solid var(--line);
  color: var(--quiet);
}

.reader .unlinked {
  border-bottom: var(--hairline) dotted var(--quiet);
  cursor: help;
}

.reader .slot.face {
  margin: calc(var(--gap) * 1.25) 0;
}

.reader > .slot.full {
  margin-top: calc(var(--gap) * 2.5);
}

.face-card h2 {
  font-size: var(--heading);
  line-height: var(--leading-tight);
  margin: 0 0 0.35em;
  font-weight: 600;
}

.face-card h2 .number {
  color: var(--quiet);
  font-weight: 400;
  margin-right: 0.45em;
}

.face-card p {
  margin: 0;
  color: var(--quiet);
  font-size: var(--aside);
  line-height: var(--leading-close);
}
`;

type Drawn = Given<BriefBody, BriefSettings>;

export default function draw(given: Drawn, space: Space) {
  return given.kind === "face" ? face(given) : full(given, space);
}

// A level on the way down: a brief, its title, and its number where it has one.
interface Level {
  id: Id;
  title: string;
  number: string;
}

async function full(given: Drawn, space: Space) {
  const holon = given.holon!;
  const brief = holon.body;
  const numbers = (whole: HolonOf<BriefBody>) => whole.body.kept !== "time";

  const levels = await wayDown(holon, space, numbers);
  const number = levels.at(-1)?.number ?? "";
  const steps = levels
    .slice(0, -1)
    .map(({ id, title, number }) => ({ to: id, label: number ? `${number} ${title}` : title }));

  return (
    <article class="place reader">
      <Way steps={steps} />
      <h1>
        {number && <span class="number">{number}</span>}
        {brief.title}
        {brief.status && <span class="status">{brief.status}</span>}
      </h1>
      <div class="prose">{proseOf(holon, space)}</div>
      {(brief.parts?.length ?? 0) > 0 &&
        space.open(
          brief.parts!.map(({ $ref }) => $ref),
          { offer: { kind: "face" }, settings: { numbered: numbers(holon), number } },
        )}
    </article>
  );
}

function face(given: Drawn) {
  const holon = given.holon!;
  const brief = holon.body;
  const { number } = given.settings;
  const first = faceOf(brief.prose);
  const beneath = brief.parts?.length ?? 0;

  return (
    <div class="card face-card">
      <h2>
        {number && <span class="number">{number}</span>}
        {brief.title}
      </h2>
      {first && <p html={first} />}
      {beneath > 0 && <span class="meta">{beneath} beneath</span>}
    </div>
  );
}

// The prose, block by block; a block that is nothing but a link into the
// field is a slot, the holon it places mounted there, offered a face, or
// in full where the link itself says so.
function proseOf(holon: HolonOf<BriefBody>, space: Space) {
  return markdown.lexer(holon.body.prose).map((token) => {
    const slot = slotOf(token);
    if (slot)
      return space.open(slot.id, {
        offer: { kind: "face" },
        ...(slot.kind === "full" ? { kind: "full" } : {}),
      });

    const kind = isConfidence(token) ? "block confidence" : "block";
    return <div class={kind} html={markdown.parser([token]) as string} />;
  });
}

// What holds a brief, and where: the whole that lists it among its parts, at
// its place there, or the whole whose prose places it by a lone link.
interface Holder {
  whole: HolonOf<BriefBody>;
  place?: number;
}

async function holderOf(holon: HolonOf<BriefBody>, space: Space): Promise<Holder | undefined> {
  for (const { id, key } of await space.read({ holders: holon.id })) {
    const whole = await space.holon<BriefBody>(id);
    if (!whole) continue;
    if (key === "parts")
      return { whole, place: (whole.body.parts ?? []).findIndex(({ $ref }) => $ref === holon.id) };
    if (key === "prose" && markdown.lexer(whole.body.prose).some((token) => placed(token) === holon.id))
      return { whole };
  }
  return undefined;
}

// From the root down to this brief, each step numbered as the rule numbers
// it: by its place among its whole's parts, running on from the whole's own
// number while the whole is a part too, and starting again across a file.
async function wayDown(
  holon: HolonOf<BriefBody>,
  space: Space,
  numbers: (whole: HolonOf<BriefBody>) => boolean,
): Promise<Level[]> {
  const up: { holon: HolonOf<BriefBody>; place?: number }[] = [];
  const seen = new Set<Id>();
  for (let at: Holder | undefined = { whole: holon }; at && !seen.has(at.whole.id); ) {
    seen.add(at.whole.id);
    const holder = await holderOf(at.whole, space);
    up.push({
      holon: at.whole,
      place: holder && holder.place !== undefined && numbers(holder.whole) ? holder.place : undefined,
    });
    at = holder;
  }
  return up.reverse().reduce<Level[]>((way, { holon, place }) => {
    const above = way.at(-1)?.number;
    const number = place === undefined ? "" : above ? `${above}.${place + 1}` : `${place + 1}`;
    return [...way, { id: holon.id, title: holon.body.title, number }];
  }, []);
}

body.prose:
A slot can read more than one holon: what an expression gathers. An expression is data, a value held in a body like any other, and the engine evaluates it to the holons it gathers, in the field's order. Its forms walk the few axes every holon has: what it is, the instances of a type or every type; how it connects, what points at a holon and what a holon points at; and where it enters, what a store holds and what the stores name; what says some words, so a search is a way of looking too; with everything, and what all or any of several gather. Held in a mount, an expression is what the mount gives, and a component may gather in what it reads, so the same field can be looked at from as many angles as there are expressions, each drawn by whatever takes it.

Gathered, a set is flat, and a flat field is never what one wants to see. So an expression can group: what it gathers, in collections, one for each value along an axis, by what it is, by what holds it, or by where it is kept. Each collection is itself a way of looking, the first narrowed by one value, so it opens like any place and is grouped again inside; layer by layer, the field is entered as it is made. A grouping by what splits it best lets the field choose: for whatever is gathered it takes the axis that gives a few groups, three to a dozen, covering most of it, and where nothing splits a set, or every holon shares a value, it is given as it is. The root gives everything, grouped so, and nothing is chosen for the reader beforehand.

```ts
{ group: { everything: true }, by: "strongest" }
// opened: Brief (230), Expression, Type, Component, …
// Brief opened: { group: { instances: ref(Brief) }, by: "strongest" }
```

*The author's, 2026-11-03: expressions are just data, so no language is invented; open the power to look upon data from different angles, which is what the reader will become. The forms the session's. A form for what a holon holds, by key, was let go the same day as convoluted: a holon's parts are its own to open. Grouping the author's, the same day: expressions are grouping, expressions are locations, in layers, a collection opened to see what is inside; if nothing is chosen, everything grouped by the strongest, and play welcome to see what works. The axes and how strength is weighed the session's, a first try.*

body.css:
/* Glass's material: everything drawn is made of these names, and nothing
   else. Colours come in a light and a dark; type is a serif to read in and a
   sans for what stands around the reading; the measure keeps a line short
   enough to read. */

:root {
  --ground: #fbfaf7;
  --raised: #ffffff;
  --ink: #23211d;
  --quiet: #6f6a61;
  --line: #e4e0d7;
  --accent: #3d5a80;

  --serif: "Iowan Old Style", "Palatino Linotype", Palatino, Georgia, serif;
  --sans: ui-sans-serif, system-ui, -apple-system, "Segoe UI", sans-serif;
  --mono: ui-monospace, "SF Mono", Menlo, Consolas, monospace;

  --text: 18px;
  --leading: 1.6;
  --leading-close: 1.5;
  --leading-tight: 1.2;
  --lead: 1.12em;
  --aside: 0.93em;
  --code: 0.8em;
  --title: 2rem;
  --heading: 1.1rem;
  --small: 0.875rem;
  --smaller: 0.75rem;

  --measure: 40rem;
  --gap: 1rem;
  --inset: 0.8em 1em;
  --radius: 8px;
  --pill: 99px;
  --hairline: 1px;
  --rule: 3px;

  color-scheme: light dark;
}

@media (prefers-color-scheme: dark) {
  :root {
    --ground: #171614;
    --raised: #1e1d1a;
    --ink: #e8e4dc;
    --quiet: #9b958a;
    --line: #2f2c28;
    --accent: #9db4d6;
  }
}

body {
  margin: 0;
  background: var(--ground);
  color: var(--ink);
  font: var(--text) / var(--leading) var(--serif);
  -webkit-font-smoothing: antialiased;
}

#glass {
  max-width: var(--measure);
  min-height: 100dvh;
  margin: 0 auto;
  padding: 0 var(--gap);
}

a {
  color: var(--accent);
}

code,
pre {
  font-family: var(--mono);
}

.glass-note {
  color: var(--quiet);
  font: var(--small) / var(--leading-close) var(--sans);
}

/* A place: what a mount draws whole. The way down to it stands above its
   title, quiet, in the sans. */

.place > nav {
  font: var(--small) / var(--leading-close) var(--sans);
  color: var(--quiet);
  margin-bottom: calc(var(--gap) * 2.5);
}

.place > nav a {
  color: inherit;
  text-decoration: none;
}

.place > nav a:hover {
  color: var(--ink);
}

.place > nav a + a::before {
  content: "›";
  margin: 0 0.5em;
  opacity: 0.6;
}

.place > h1 {
  font-size: var(--title);
  line-height: var(--leading-tight);
  font-weight: 600;
  margin: 0 0 calc(var(--gap) * 1.25);
  letter-spacing: -0.01em;
}

.place > h2 {
  font: var(--small) / var(--leading-close) var(--sans);
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--quiet);
  margin: calc(var(--gap) * 2.5) 0 calc(var(--gap) * 0.75);
}

.place pre {
  background: var(--raised);
  border: var(--hairline) solid var(--line);
  border-radius: var(--radius);
  padding: var(--inset);
  overflow: auto;
  max-height: 32rem;
  font-size: var(--code);
  line-height: var(--leading-close);
}

/* What is said about a thing beside it, small and quiet. */

.meta {
  display: block;
  font: var(--smaller) / var(--leading-close) var(--sans);
  color: var(--quiet);
}

/* A card: what a face slot draws, entered by a press. The slot is what is
   pressed and focused, so it is the slot that marks the card. */

.card {
  display: block;
  padding: var(--gap) calc(var(--gap) * 1.15);
  border: var(--hairline) solid var(--line);
  border-radius: var(--radius);
  background: var(--raised);
  cursor: pointer;
  transition: border-color 0.15s;
}

.slot.face:hover > .card,
.slot.face:focus-visible > .card {
  border-color: var(--quiet);
}

.slot.face:focus-visible {
  outline: none;
}

.card .meta {
  margin-top: 0.5em;
}

/* A list: its items one under another. */

.list {
  list-style: none;
  padding: 0;
  margin: 0;
  display: grid;
  gap: calc(var(--gap) * 0.75);
}

/* A component made of data: its mounts one under another, set off by
   space. */

.template {
  padding: calc(var(--gap) * 3) 0 calc(var(--gap) * 6);
}

.template > .slot + .slot {
  margin-top: calc(var(--gap) * 2);
}

/* A grouping's collections, side by side where there is room. */

.collections {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(12rem, 1fr));
  gap: calc(var(--gap) * 0.75);
  margin: 0 0 calc(var(--gap) * 1.5);
}

/* A list's items as cards, side by side where there is room. */

.list.cards {
  grid-template-columns: repeat(auto-fill, minmax(14rem, 1fr));
}

/* A search: where one stands, its parts as chips beside what is typed,
   and what is found beneath. Above what it searches from, it stays at the
   top as the page moves, and shows what it found while it holds the
   focus; in a menu, always. */

.search {
  position: relative;
  font: var(--small) / var(--leading-close) var(--sans);
}

.template > .slot:first-child:has(> .search) {
  position: sticky;
  top: 0;
  z-index: 5;
  background: var(--ground);
  padding: 0.6rem 0;
  margin-top: calc(var(--gap) * -2);
}

.search-field {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 0.3rem;
  padding: 0.35rem 0.45rem;
  background: var(--raised);
  border: var(--hairline) solid var(--line);
  border-radius: var(--radius);
}

.search-field:focus-within {
  border-color: var(--quiet);
}

.search .part {
  display: inline-flex;
  align-items: center;
  gap: 0.15rem;
  padding: 0.15em 0.25em 0.15em 0.6em;
  border: 0;
  border-radius: var(--pill);
  background: var(--line);
  color: var(--ink);
  font: inherit;
  white-space: nowrap;
}

.search button.part {
  padding-right: 0.6em;
  background: none;
  color: var(--quiet);
  cursor: pointer;
}

.search button.part:hover,
.search button.part:focus-visible {
  color: var(--ink);
  outline: none;
}

.search .part-change {
  display: inline-flex;
  gap: 0.3em;
  padding: 0;
  border: 0;
  background: none;
  color: inherit;
  font: inherit;
  cursor: pointer;
}

.search .part-change:disabled {
  cursor: default;
}

.search .part-field {
  color: var(--quiet);
}

.search .part-change:not(:disabled):hover .part-value,
.search .part-change:focus-visible .part-value {
  text-decoration: underline;
  outline: none;
}

.search .part.pending {
  padding-right: 0.6em;
  background: none;
  color: var(--accent);
  font-weight: 600;
}

.search .part.pending[hidden] {
  display: none;
}

.search .let-go {
  border: 0;
  background: none;
  color: var(--quiet);
  font: inherit;
  line-height: 1;
  padding: 0 0.3em;
  border-radius: var(--pill);
  cursor: pointer;
}

.search .let-go:hover,
.search .let-go:focus-visible {
  color: var(--ink);
  background: var(--ground);
  outline: none;
}

.search-input {
  flex: 1 1 10rem;
  min-width: 8rem;
  padding: 0.25em 0.2em;
  border: 0;
  background: none;
  color: var(--ink);
  font: inherit;
  outline: none;
}

.search-found {
  display: none;
  list-style: none;
  margin: 0.3rem 0 0;
  padding: 0.3rem;
  max-height: min(24rem, 60vh);
  overflow-y: auto;
  background: var(--raised);
  border: var(--hairline) solid var(--line);
  border-radius: var(--radius);
}

.search:focus-within .search-found:not(:empty),
.search.pressed .search-found:not(:empty) {
  display: block;
}

.slot:not(.menu *) > .search .search-found {
  position: absolute;
  left: 0;
  right: 0;
  box-shadow: 0 0.5rem 1.5rem rgb(0 0 0 / 0.12);
}

.found {
  display: flex;
  align-items: center;
  gap: 0.3rem;
  border-radius: calc(var(--radius) - 2px);
}

.found.active,
.found:hover {
  background: var(--ground);
}

.found .lead {
  flex: 1;
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 1rem;
  min-width: 0;
  padding: 0.4rem 0.55rem;
  border: 0;
  background: none;
  color: var(--ink);
  font: inherit;
  text-align: left;
  cursor: pointer;
}

.found-said {
  display: block;
  padding: 0.4rem 0.55rem;
  color: var(--quiet);
}

.found-label {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.found .meta {
  flex-shrink: 0;
  max-width: 50%;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

/* A mount's menu: the search, laid where the press landed. */

.menu {
  position: fixed;
  z-index: 10;
  width: min(30rem, calc(100vw - 16px));
  padding: 0.35rem;
  background: var(--ground);
  border: var(--hairline) solid var(--line);
  border-radius: var(--radius);
  box-shadow: 0 0.5rem 1.5rem rgb(0 0 0 / 0.18);
}
